<template><section class="smart-favorites"><header><h1>智能收藏夹</h1><div class="smart-tabs"><button v-for="t in tabs" :key="t.id" :class="{on:kind===t.id}" @click="select(t.id)">{{t.label}}</button></div></header><p class="smart-note">{{warning||hint}}</p><PagedCarousel :loader="load" :query-key="kind+':'+revision" :page-size="6" :columns="2"><template #default="{items}"><article v-for="item in items" :key="item.key||item.song?.id||item.title" class="smart-card"><button class="smart-pick" @click="order(item)"><span><b>{{item.song?.title||item.title}}</b><small>{{(item.song?.artist||item.artists?.join(' / '))+(item.song?.source==='bilibili'?' · '+formatVideoViews(item.song.views):'')}}</small><em>{{item.reason}}</em></span><strong>{{isOrdered(item)?'已点':item.available?'点歌':'B站找歌'}}</strong></button><button v-if="kind==='manual'&&item.song" class="smart-remove" @click="remove(item)">取消收藏</button></article></template></PagedCarousel></section></template>
<script setup>
import {formatVideoViews} from '../utils/videoViews'
import {computed,ref} from 'vue'
import {useRouter} from 'vue-router'
import PagedCarousel from '../components/PagedCarousel.vue'
import api from '../api/client'
import {useFavoritesStore} from '../stores/favorites'
import {usePlayerStore} from '../stores/player'
import {useToast} from '../composables/useToast'
const tabs=[{id:'manual',label:'我的收藏'},{id:'sung',label:'唱过的'},{id:'frequent',label:'经常唱'},{id:'bilibili',label:'B站点播过'}]
const kind=ref('manual'),revision=ref(0),warning=ref(''),router=useRouter(),player=usePlayerStore(),favorites=useFavoritesStore(),{toast}=useToast();let cursors=new Map([[0,'']])
const hint=computed(()=>({manual:'你手动收藏的歌曲',sung:'累计播放至少30秒或完整唱完的歌；完整完成另计',frequent:'有至少两次播放记录且累计至少60秒，按播放次数排序',bilibili:'在这里点播过的B站视频，自动整理'}[kind.value]))
function select(id){kind.value=id;revision.value++;cursors=new Map([[0,'']]);warning.value=''}
async function load(page){const type=kind.value,rev=revision.value,map=cursors;const after=map.get(page);if(after===undefined)throw Error('请按顺序翻页');const data=await api.smartFavorites(type,after,6);if(type!==kind.value||rev!==revision.value)return [];warning.value=data.warning||'';if(data.after)map.set(page+1,data.after);return data.hasMore?[...data.items,null]:data.items}
function isOrdered(item){return !!item.song&&player.orderedSongIds.has(String(item.song.id))}
async function order(item){if(isOrdered(item)){toast('这首歌已点');return}if(!item.available||!item.song){router.push({name:'bilibili',query:{keyword:[item.title,...(item.artists||[]),'MV'].join(' '),matchTitle:item.title,matchArtists:JSON.stringify(item.artists||[])}});return}try{player.applySnapshot(await api.control('order',{song_id:item.song.id,origin:'replay'}));toast('已加入队列')}catch(e){toast(e.message)}}
async function remove(item){try{await api.removeFavorite(item.song.id);favorites.ids=favorites.ids.filter(id=>String(id)!==String(item.song.id));select('manual');toast('已取消手动收藏')}catch(e){toast(e.message)}}
</script>
<style scoped>
.smart-favorites{height:100%;min-height:0;display:flex;flex-direction:column;gap:8px}.smart-favorites>header{display:flex;align-items:center;gap:20px}.smart-favorites h1{font-size:20px;font-weight:600}.smart-tabs{display:flex;gap:8px}.smart-tabs button{padding:8px 14px;border:1px solid var(--line);border-radius:9px;background:var(--panel2);color:var(--dim);font-size:13px}.smart-tabs .on{color:var(--gold);border-color:var(--accent-line);background:var(--selected)}.smart-note{font-size:11px;color:var(--dim2);margin:0}.smart-favorites>.paged-carousel{flex:1;min-height:0}.smart-card{min-height:0;display:flex;align-items:stretch;background:var(--tile);border:1px solid var(--glass-border);border-radius:12px;overflow:hidden;margin:3px 0}.smart-pick{display:flex;align-items:center;flex:1;min-width:0;gap:10px;padding:10px 14px;text-align:left}.smart-pick>span{min-width:0;flex:1}.smart-pick b,.smart-pick small,.smart-pick em{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.smart-pick b{font-size:16px;font-weight:600;line-height:1.4}.smart-pick small{font-size:12px;color:var(--dim);margin-top:4px}.smart-pick em{font-size:10px;font-style:normal;color:var(--gold);margin-top:4px}.smart-pick strong{font-size:11px;font-weight:400;color:var(--gold);flex:none}.smart-remove{font-size:11px;color:var(--dim);padding:8px;background:var(--panel2);width:64px;flex:none}
</style>
